<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { alternarTipo, guardarTipo, listarTipos } from '../services/configuracion'
import type { TipoDocumentoConfig } from '../interfaces/configuracion.interface'
const criterio=ref(''),items=ref<TipoDocumentoConfig[]>([]),pagination=reactive({current:1,last:1,total:0}),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive({nombre:'',descripcion:'',tamanio_maximo_mb:10,activo:true,es_convenio:false,es_documento_normativo:false,es_proveido:false})
async function load(page=1){loading.value=true;error.value='';try{const r=await listarTipos(criterio.value,page);items.value=r.data;Object.assign(pagination,{current:r.current_page,last:r.last_page,total:r.total})}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo cargar la configuración.'}finally{loading.value=false}}
function open(item?:TipoDocumentoConfig){editing.value=item?.id||null;Object.assign(form,item?{nombre:item.nombre,descripcion:item.descripcion||'',tamanio_maximo_mb:item.tamanio_maximo_mb,activo:item.activo,es_convenio:item.es_convenio,es_documento_normativo:item.es_documento_normativo,es_proveido:item.es_proveido}:{nombre:'',descripcion:'',tamanio_maximo_mb:10,activo:true,es_convenio:false,es_documento_normativo:false,es_proveido:false});modal.value=true}
async function save(){if(!form.nombre.trim()){error.value='Ingrese el nombre del tipo documental.';return}saving.value=true;try{await guardarTipo(editing.value,{...form,nombre:form.nombre.trim()});success.value=editing.value?'Tipo documental actualizado.':'Tipo documental registrado.';modal.value=false;await load(editing.value?pagination.current:1)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo guardar.'}finally{saving.value=false}}
async function toggle(item:TipoDocumentoConfig){try{await alternarTipo(item.id);success.value=`Tipo documental ${item.activo?'desactivado':'activado'}.`;await load(pagination.current)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo cambiar el estado.'}}
onMounted(()=>load())
</script>
<template><div class="config"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/tramite">Trámite V2</RouterLink> / Configuración / Tipos de documento</nav><header class="hero"><div class="mark">TR</div><div><small>Configuración</small><h1>Tipos de documento</h1><p>Define las clases documentales disponibles y sus características.</p></div><strong>{{pagination.total}} registros</strong><button @click="open()">+ Nuevo tipo</button></header><div v-if="success" class="success">✓ {{success}}</div><form class="filters" @submit.prevent="load()"><label><span>Buscar por nombre</span><input v-model.trim="criterio" placeholder="Tipo documental"></label><button>Buscar</button><button type="button" class="clear" @click="criterio='';load()">Limpiar</button></form><div v-if="error" class="notice error">{{error}}</div><div v-else-if="loading" class="notice">Cargando tipos documentales…</div><div v-else-if="!items.length" class="notice">No hay tipos documentales registrados.</div><section v-else class="table"><table><thead><tr><th>Tipo documental</th><th>Tamaño</th><th>Características</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="i in items" :key="i.id"><td><b>{{i.nombre}}</b><small>{{i.descripcion||'Sin descripción'}}</small></td><td>{{i.tamanio_maximo_mb}} MB</td><td><div class="tags"><span v-if="i.es_convenio">Convenio</span><span v-if="i.es_documento_normativo">Normativo</span><span v-if="i.es_proveido">Proveído</span><em v-if="!i.es_convenio&&!i.es_documento_normativo&&!i.es_proveido">General</em></div></td><td><span :class="['status',{off:!i.activo}]">{{i.activo?'Activo':'Inactivo'}}</span></td><td><button @click="open(i)">Editar</button><button class="toggle" @click="toggle(i)">{{i.activo?'Desactivar':'Activar'}}</button></td></tr></tbody></table></section><footer v-if="pagination.last>1" class="pagination"><button :disabled="pagination.current===1" @click="load(pagination.current-1)">Anterior</button><span>Página {{pagination.current}} de {{pagination.last}}</span><button :disabled="pagination.current===pagination.last" @click="load(pagination.current+1)">Siguiente</button></footer><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><section class="modal"><header><div><small>Tipo documental</small><h2>{{editing?'Editar':'Registrar'}} tipo de documento</h2></div><button @click="modal=false">×</button></header><form @submit.prevent="save"><label><span>Nombre *</span><input v-model.trim="form.nombre" maxlength="100"></label><label><span>Descripción</span><textarea v-model.trim="form.descripcion" rows="3"></textarea></label><label><span>Tamaño máximo (MB)</span><input v-model.number="form.tamanio_maximo_mb" type="number" min="1" max="100"></label><div class="checks"><label><input v-model="form.activo" type="checkbox"> Activo</label><label><input v-model="form.es_convenio" type="checkbox"> Convenio</label><label><input v-model="form.es_documento_normativo" type="checkbox"> Documento normativo</label><label><input v-model="form.es_proveido" type="checkbox"> Proveído</label></div><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></section></div></div></template>
<style scoped>
.config{--accent:#6657bd;color:#35464e}nav{margin-bottom:17px;color:#98a4aa;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.62rem;font-weight:700;text-transform:uppercase}.hero h1{margin:2px 0;font-size:1.38rem}.hero p{margin:0;color:#7d898f;font-size:.72rem}.hero>strong{margin-left:auto;font-size:.65rem}.hero>button,.filters button,.pagination button,.table button,.modal footer button{padding:8px 12px;border:1px solid var(--accent);border-radius:7px;color:#fff;background:var(--accent);font-size:.63rem}.success{margin-top:14px;padding:11px;border:1px solid #b9dfce;border-radius:8px;color:#276b50;background:#eff9f4;font-size:.68rem}.filters{margin:16px 0;padding:18px;display:grid;grid-template-columns:1fr auto auto;align-items:end;gap:8px;border:1px solid #e2e7ea;border-radius:11px;background:#fff}label>span{display:block;margin-bottom:6px;color:#66737a;font-size:.64rem}input,textarea{width:100%;padding:9px 10px;border:1px solid #dae2e6;border-radius:7px;font:inherit;font-size:.69rem}.clear{color:#68757c!important;border-color:#d5dee2!important;background:#fff!important}.notice{padding:45px;text-align:center;border:1px dashed #cbd6dc;border-radius:10px;background:#fff;font-size:.7rem}.notice.error{color:#a13f43}.table{overflow:auto;border:1px solid #e0e6e9;border-radius:11px;background:#fff}table{width:100%;border-collapse:collapse;min-width:750px}th,td{padding:12px;text-align:left;border-top:1px solid #edf0f2;font-size:.65rem}th{border:0;color:#77848b;background:#f5f7f8;text-transform:uppercase;font-size:.57rem}td b,td small{display:block}td small{margin-top:3px;color:#8b979d}.tags{display:flex;gap:4px}.tags span,.tags em,.status{padding:4px 6px;border-radius:11px;color:#55489e;background:#eeeafa;font-size:.54rem;font-style:normal}.status{color:#247054;background:#e5f6ee}.status.off{color:#707a7f;background:#e9edef}.table td:last-child{display:flex;gap:5px}.table .toggle{color:#7c5c19;border-color:#f3d591;background:#fff2cf}.pagination{padding:18px;display:flex;justify-content:center;align-items:center;gap:12px;font-size:.64rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,520px);border-radius:12px;background:#fff}.modal>header{padding:18px 20px;display:flex;border-bottom:1px solid #e5eaed}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal>form{padding:20px}.modal form>label{display:block;margin-bottom:13px}.checks{display:grid;grid-template-columns:1fr 1fr;gap:8px}.checks label{font-size:.65rem}.checks input{width:auto}.modal footer{margin-top:18px;display:flex;justify-content:flex-end;gap:7px}@media(max-width:650px){.hero{flex-wrap:wrap}.hero>strong{margin-left:0}.hero>button{width:100%}.filters{grid-template-columns:1fr}.checks{grid-template-columns:1fr}}
</style>
